window.TRIGGLE_REAL_PATH.stages.forEach((stage,index)=>{
  const ladders=[[{"label":{"en":"Start with a fraction","ta":"பின்னத்தில் தொடங்குவோம்"},"explain":{"en":"A rational number is a fraction of two integers. The denominator must not be zero. Even 0 and negative integers are rational.","ta":"இரு முழுக்களின் விகிதமாக எழுதக்கூடிய எண் விகிதமுறு எண். பகுதி பூச்சியமாக இருக்கக் கூடாது. பூச்சியமும் எதிர்மறை முழுக்களும் விகிதமுறு எண்களே."},"math":{"latex":"-\\dfrac{3}{4},\\quad 0=\\dfrac{0}{1},\\quad -2=\\dfrac{-2}{1}","fallback":"−3/4, 0=0/1, −2=−2/1"}},{"label":{"en":"Find a number in between","ta":"இடையிலுள்ள எண்ணைக் காண்போம்"},"explain":{"en":"First rewrite the endpoints with a common denominator. The numerator 7 lies strictly between 6 and 8.","ta":"இரு பின்னங்களின் பகுதிகளைச் சமமாக்குக. 6 மற்றும் 8 இடையே 7 இருப்பதால் அந்தப் பின்னம் இடையில் அமைகிறது."},"math":{"latex":"\\dfrac12=\\dfrac6{12}<\\dfrac7{12}<\\dfrac8{12}=\\dfrac23","fallback":"1/2=6/12 < 7/12 < 8/12=2/3"}},{"label":{"en":"Repeat forever","ta":"எண்ணற்ற எண்களைக் காண்போம்"},"explain":{"en":"Take the midpoint of any two distinct rational numbers. You can repeat this with the smaller interval, so there is no next rational number.","ta":"வெவ்வேறு இரண்டு விகிதமுறு எண்களின் சராசரியைக் காண்க. புதிய சிறிய இடைவெளியிலும் இதையே மீண்டும் செய்யலாம்; எனவே இடையில் எண்ணற்ற எண்கள் உள்ளன."},"math":{"latex":"\\dfrac{\\frac12+\\frac7{12}}{2}=\\dfrac{13}{24}","fallback":"(1/2+7/12)/2=13/24"}}],[{"label":{"en":"Meet an irrational number","ta":"விகிதமுறா எண்ணை அறிக"},"explain":{"en":"The diagonal of a unit square is √2. It is an exact length, even though its decimal digits never end or repeat.","ta":"ஒரு அலகுச் சதுரத்தின் மூலைவிட்ட நீளம் √2. அதன் தசம இலக்கங்கள் முடிவுறாமலும் மீளாமலும் இருந்தாலும் இது துல்லியமான நீளமே."},"math":{"latex":"1^2+1^2=2,\\quad d=\\sqrt2","fallback":"1²+1²=2, d=√2"}},{"label":{"en":"Classify the decimal","ta":"தசமத்தை வகைப்படுத்துக"},"explain":{"en":"Terminating and eventually repeating decimals are rational. A non-terminating, non-repeating decimal is irrational.","ta":"முடிவுறும் தசமங்களும் ஒரு கட்டத்திலிருந்து மீண்டும் வரும் தசமங்களும் விகிதமுறு எண்கள். முடிவுறாமலும் மீளாமலும் உள்ள தசமம் விகிதமுறா எண்."},"math":{"latex":"\\dfrac18=0.125,\\quad \\dfrac13=0.\\overline3,\\quad \\sqrt2=1.4142\\ldots","fallback":"1/8=0.125; 1/3=0.333…; √2=1.4142…"}},{"label":{"en":"Turn repetition into a fraction","ta":"மீளும் தசமத்தை பின்னமாக்குக"},"explain":{"en":"Let x be the repeating decimal. Move the decimal point by two places, then subtract; the repeating tail cancels.","ta":"மீளும் தசமத்தை x என்க. தசமப்புள்ளியை இரண்டு இடங்கள் நகர்த்தி கழித்தால் மீளும் பகுதி நீங்கிவிடும்."},"math":{"latex":"x=0.\\overline{27},\\quad 100x-x=27,\\quad x=\\dfrac{3}{11}","fallback":"x=0.(27), 99x=27, x=3/11"}},{"label":{"en":"Check when a fraction ends","ta":"எப்போது தசமம் முடியும்?"},"explain":{"en":"Simplify the fraction first. Its decimal terminates exactly when the remaining denominator has no prime factors except 2 and 5.","ta":"முதலில் பின்னத்தைச் சுருக்குக. அதன் பகுதியில் 2, 5 தவிர வேறு பகா காரணிகள் இல்லையெனில் மட்டுமே தசமம் முடிவுறும்."},"math":{"latex":"\\dfrac3{40}=0.075,\\qquad \\dfrac16=0.1\\overline6","fallback":"3/40=0.075; 1/6=0.1666…"}}],[{"label":{"en":"Build an exact root","ta":"துல்லியமான மூலத்தை உருவாக்குக"},"explain":{"en":"A right triangle with legs 1 and 1 has hypotenuse √2. That distance can be transferred to a number line.","ta":"செங்கோண முக்கோணத்தின் மற்ற இரு பக்கங்களும் 1 எனில் கர்ணம் √2. அந்த நீளத்தை எண்கோட்டில் குறிக்கலாம்."},"math":{"latex":"d^2=1^2+1^2,\\qquad d=\\sqrt2","fallback":"d²=1²+1², d=√2"}},{"label":{"en":"Zoom once, then again","ta":"மீண்டும் மீண்டும் பெரிதாக்குக"},"explain":{"en":"Each extra decimal digit chooses one of ten smaller intervals. The root is within all three intervals, not equal to a rounded endpoint.","ta":"ஒவ்வொரு புதிய தசம இலக்கமும் முந்தைய இடைவெளியைப் பத்து சிறு இடைவெளிகளாகப் பிரிக்கிறது. மூலம் இந்த இடைவெளிகளுக்குள் இருக்கும்; வட்டமிட்ட எல்லை மதிப்புக்குச் சமமல்ல."},"math":{"latex":"1.4<\\sqrt2<1.5,\\quad 1.41<\\sqrt2<1.42","fallback":"1.4<√2<1.5; 1.41<√2<1.42"}},{"label":{"en":"All numbers share one line","ta":"எல்லா மெய்யெண்களும் ஒரே கோட்டில்"},"explain":{"en":"Rational and irrational numbers together form the real numbers. Each real number corresponds to one point on the real-number line.","ta":"விகிதமுறு மற்றும் விகிதமுறா எண்கள் சேர்ந்து மெய்யெண்களாகும். ஒவ்வொரு மெய்யெண்ணுக்கும் எண்கோட்டில் ஓர் இடம் உண்டு."},"math":{"latex":"\\mathbb{R}=\\mathbb{Q}\\cup\\{\\text{irrational real numbers}\\}","fallback":"Real numbers = rational numbers ∪ irrational numbers"}}],[{"label":{"en":"A root is a power","ta":"மூலம் என்பது ஓர் அடுக்கு"},"explain":{"en":"The square root means the positive number that squares to the given value; the nth root is represented by an exponent of 1/n when defined in real numbers.","ta":"வர்க்கமூலம் என்பது வர்க்கப்படுத்தினால் கொடுக்கப்பட்ட எண்ணைப் பெறும் எதிர்மறையற்ற எண். மெய்யெண்களில் வரையறுக்கப்படும் n-ஆம் மூலம் 1/n அடுக்காக எழுதப்படும்."},"math":{"latex":"a^{1/n}=\\sqrt[n]{a},\\qquad 16^{1/2}=4","fallback":"a^(1/n)=n-th root of a; 16^(1/2)=4"}},{"label":{"en":"Read a fractional index","ta":"பின்ன அடுக்கைப் புரிந்துகொள்"},"explain":{"en":"The denominator of the exponent names the root; the numerator tells how many times to multiply the root.","ta":"அடுக்கின் பகுதி எந்த மூலம் என்பதைக் காட்டும்; தொகுதி அந்த மூலத்தை எத்தனை முறை பெருக்க வேண்டும் என்பதைக் காட்டும்."},"math":{"latex":"8^{2/3}=(\\sqrt[3]8)^2=2^2=4","fallback":"8^(2/3)=(cube root 8)²=4"}},{"label":{"en":"A negative exponent means reciprocal","ta":"எதிர்மறை அடுக்கு தலைகீழைக் குறிக்கும்"},"explain":{"en":"Apply the fractional exponent, then take its reciprocal. The base must be nonzero for negative powers.","ta":"முதலில் பின்ன அடுக்கைக் கணக்கிட்டு, பின்னர் தலைகீழைப் பெறுக. எதிர்மறை அடுக்கிற்கு அடிமானம் பூச்சியமாக இருக்கக் கூடாது."},"math":{"latex":"4^{-3/2}=\\dfrac{1}{(\\sqrt4)^3}=\\dfrac18","fallback":"4^(−3/2)=1/(√4)³=1/8"}}],[{"label":{"en":"Recognise and simplify a surd","ta":"முறுடை அறிந்து சுருக்குக"},"explain":{"en":"√8 is a second-order surd; √16=4 is not a surd. Extract the largest square factor before doing any operation.","ta":"√8 என்பது இரண்டாம் படி முறுடு; √16=4 முறுடு அல்ல. செயல் செய்வதற்கு முன் பெரிய நிறைவர்க்கக் காரணியை வெளியே எடுக்கவும்."},"math":{"latex":"\\sqrt8=\\sqrt{4\\times2}=2\\sqrt2,\\quad \\sqrt{16}=4","fallback":"√8=√(4×2)=2√2; √16=4"}},{"label":{"en":"Only like surds add","ta":"ஒரே முறுடுகளை மட்டும் கூட்டுக"},"explain":{"en":"Simplify both roots. The coefficients 2 and 3 can be added because the remaining radical part is the same.","ta":"இரண்டு மூலங்களையும் சுருக்குக. மீதமுள்ள மூலப் பகுதி ஒரே √3 என்பதால் 2, 3 கெழுக்களைக் கூட்டலாம்."},"math":{"latex":"\\sqrt{12}+\\sqrt{27}=2\\sqrt3+3\\sqrt3=5\\sqrt3","fallback":"√12+√27=2√3+3√3=5√3"}},{"label":{"en":"Multiply or divide the roots","ta":"மூலங்களைப் பெருக்கவும் வகுக்கவும்"},"explain":{"en":"For nonnegative real radicands, multiplication and division combine under one root (the divisor must not be zero). Unlike roots do not add directly.","ta":"எதிர்மறையற்ற மெய்யெண்களில் மூலங்களின் பெருக்கல், வகுத்தல் ஒரே மூலக்குறிக்குள் அமையும் (வகுப்பான் பூச்சியமல்ல). வெவ்வேறு முறுடுகளை நேரடியாகக் கூட்ட முடியாது."},"math":{"latex":"\\sqrt6\\,\\sqrt3=3\\sqrt2,\\qquad \\dfrac{\\sqrt{12}}{\\sqrt3}=2","fallback":"√6×√3=3√2; √12/√3=2"}},{"label":{"en":"Check the order","ta":"முறுடின் படியை அறிக"},"explain":{"en":"Square roots are second-order radicals and cube roots are third-order radicals. Do not combine different orders as if they were like surds.","ta":"வர்க்கமூலம் இரண்டாம் படி; கனமூலம் மூன்றாம் படி. வெவ்வேறு படிகளைக் கொண்ட முறுடுகளை ஒரே மாதிரியாகச் சேர்க்க வேண்டாம்."},"math":{"latex":"\\sqrt[3]8=2,\\qquad \\sqrt[3]2\\ne\\sqrt2","fallback":"cube root 8=2; cube root 2 ≠ √2"}}],[{"label":{"en":"Keep a fraction unchanged","ta":"பின்னத்தின் மதிப்பை மாற்றாதே"},"explain":{"en":"To remove a square root from the denominator, multiply numerator and denominator by the same nonzero expression.","ta":"பின்னத்தின் கீழுள்ள மூலத்தை நீக்க, தொகுதியையும் பகுதியையும் ஒரே பூச்சியமற்ற கோவையால் பெருக்குக."},"math":{"latex":"\\dfrac1{\\sqrt5}\\times\\dfrac{\\sqrt5}{\\sqrt5}=\\dfrac{\\sqrt5}{5}","fallback":"1/√5 × √5/√5 = √5/5"}},{"label":{"en":"Spot a conjugate pair","ta":"இணை முறுடுகளை அறிக"},"explain":{"en":"Two expressions that differ only in the sign between terms are conjugates. Their product uses the difference of squares.","ta":"இரு உறுப்புகளுக்கு இடையிலான குறி மட்டும் மாறினால் அவை இணை முறுடுகள். அவற்றின் பெருக்கலில் வர்க்கங்களின் வித்தியாசம் கிடைக்கும்."},"math":{"latex":"(\\sqrt7+2)(\\sqrt7-2)=7-4=3","fallback":"(√7+2)(√7−2)=7−4=3"}},{"label":{"en":"Rationalise a two-term denominator","ta":"இரு உறுப்பு பகுதியை விகிதப்படுத்துக"},"explain":{"en":"Multiply the whole numerator and denominator by the conjugate, simplify the denominator, and cancel the common nonzero factor.","ta":"முழுத் தொகுதி, பகுதியை இணை முறுடால் பெருக்கி, பகுதியைச் சுருக்கி, பூச்சியமற்ற பொது காரணியை நீக்குக."},"math":{"latex":"\\dfrac3{\\sqrt7+2}=\\dfrac{3(\\sqrt7-2)}{7-4}=\\sqrt7-2","fallback":"3/(√7+2)=3(√7−2)/(7−4)=√7−2"}}],[{"label":{"en":"Recognise the standard form","ta":"செந்தர வடிவை அறிக"},"explain":{"en":"Write any nonzero number as a coefficient times a power of ten. The coefficient's absolute value is at least 1 but less than 10.","ta":"பூச்சியமற்ற எந்த எண்ணையும் ஒரு கெழுவையும் பத்தின் அடுக்கையும் பெருக்கி எழுதலாம். கெழுவின் தனிமதிப்பு 1-க்கு குறையாமலும் 10-க்கு குறைவாகவும் இருக்க வேண்டும்."},"math":{"latex":"a\\times10^n,\\quad 1\\leq |a|<10","fallback":"a×10^n, 1≤|a|<10"}},{"label":{"en":"Large means positive exponent","ta":"பெரிய எண்: நேர்மறை அடுக்கு"},"explain":{"en":"Move the decimal point left six places to leave 7.2. Compensate with 10 to the power +6.","ta":"தசமப்புள்ளியை ஆறு இடங்கள் இடப்புறம் நகர்த்தி 7.2 பெறுக. அதற்குப் பதிலாக +6 அடுக்கைப் பயன்படுத்துக."},"math":{"latex":"7{,}200{,}000=7.2\\times10^6","fallback":"7,200,000=7.2×10⁶"}},{"label":{"en":"Small means negative exponent","ta":"சிறிய எண்: எதிர்மறை அடுக்கு"},"explain":{"en":"Move the decimal point right four places to make 6.4. The original number must be multiplied by 10 to the power −4.","ta":"தசமப்புள்ளியை நான்கு இடங்கள் வலப்புறம் நகர்த்தி 6.4 பெறுக. ஆரம்ப எண்ணிற்கு −4 அடுக்குப் பயன்படுத்துக."},"math":{"latex":"0.00064=6.4\\times10^{-4}","fallback":"0.00064=6.4×10⁻⁴"}},{"label":{"en":"Calculate with powers of ten","ta":"பத்தின் அடுக்குகளுடன் கணக்கிடுக"},"explain":{"en":"Multiply coefficients and add exponents. Normalise the final coefficient if it falls outside 1 to 10.","ta":"கெழுக்களைப் பெருக்கி அடுக்குகளைக் கூட்டுக. இறுதிக் கெழு 1 முதல் 10 வரையிலில்லாவிட்டால் செந்தர வடிவில் மாற்றுக."},"math":{"latex":"(3\\times10^4)(2\\times10^{-2})=6\\times10^2","fallback":"(3×10⁴)(2×10⁻²)=6×10²"}}],[{"label":{"en":"Separate rational from irrational","ta":"இருவகை எண்களையும் வேறுபடுத்து"},"explain":{"en":"A square root is not automatically irrational: a perfect square gives a rational result. The decimal expansion, not the symbol alone, determines the class.","ta":"வர்க்கமூலம் என்றாலே விகிதமுறா எண் அல்ல; நிறைவர்க்கத்தின் மூலம் விகிதமுறு எண். குறியை மட்டும் அல்லாமல் எண்ணின் மதிப்பைக் கவனிக்கவும்."},"math":{"latex":"\\sqrt{49}=7\\in\\mathbb{Q},\\qquad \\sqrt3\\notin\\mathbb{Q}","fallback":"√49=7 is rational; √3 is irrational"}},{"label":{"en":"Root symbol versus equation","ta":"மூலக்குறியும் சமன்பாடும்"},"explain":{"en":"√25 names the nonnegative square root only. Solving x²=25 asks for every number whose square is 25, so both signs work.","ta":"√25 என்பது எதிர்மறையற்ற வர்க்கமூலம் மட்டும். x²=25 என்ற சமன்பாட்டில் வர்க்கம் 25 ஆகும் எல்லா மதிப்புகளும் தேவை; இரண்டு குறிகளும் பொருந்தும்."},"math":{"latex":"\\sqrt{25}=5,\\qquad x^2=25\\Rightarrow x=\\pm5","fallback":"√25=5; x²=25 ⇒ x=±5"}},{"label":{"en":"Trust exact form before rounding","ta":"தோராயத்திற்கு முன் துல்லியம்"},"explain":{"en":"Use √2 as an exact value; 1.414 is only an approximation. Simplify like surds and rationalise before rounding an answer.","ta":"√2 என்பது துல்லியமான மதிப்பு; 1.414 என்பது தோராயம் மட்டுமே. இறுதி தோராய மதிப்புக்கு முன் முறுடுகளைச் சுருக்கி, தேவைப்பட்டால் விகிதப்படுத்துக."},"math":{"latex":"\\sqrt2\\approx1.414,\\qquad \\sqrt2\\ne1.414","fallback":"√2≈1.414; √2≠1.414"}}]];
  const hints=[{"en":"Convert both endpoints to twelfths, then choose a numerator strictly between 6 and 8.","ta":"இரு எல்லைகளையும் பன்னிரண்டில் ஒரு பகுதியாக மாற்றி, 6 மற்றும் 8 இடையே உள்ள தொகுதியைத் தேர்க."},{"en":"A decimal that stops or repeats is rational. Which choice has digits that never repeat?","ta":"முடிவுறும் அல்லது மீளும் தசமம் விகிதமுறு எண். முடிவுறாமலும் மீளாமலும் உள்ளதைத் தேர்க."},{"en":"Write 5.348 to three decimal places, then compare it with 5.340 and 5.350.","ta":"5.348-ஐ மூன்று தசம இடங்களில் எழுதி 5.340, 5.350 உடன் ஒப்பிடுக."},{"en":"Look for a positive number whose fourth power equals 81.","ta":"நான்காம் அடுக்கு 81 தரும் நேர்மறை எண்ணைக் காண்க."},{"en":"Extract perfect-square factors: 12=4×3 and 27=9×3.","ta":"நிறைவர்க்கக் காரணிகளைப் பிரிக்கவும்: 12=4×3, 27=9×3."},{"en":"Multiply the numerator and denominator of [[1|√5]] by √5.","ta":"[[1|√5]] என்ற பின்னத்தின் தொகுதியையும் பகுதியையும் √5-ஆல் பெருக்குக."},{"en":"Move the decimal point four places right to obtain 6.4; compensate with a negative exponent.","ta":"தசமப்புள்ளியை நான்கு இடங்கள் வலப்புறம் நகர்த்தி 6.4 பெறுக; எதிர்மறை அடுக்கை எழுதுக."},{"en":"√25 names only the nonnegative root. Do not confuse it with the equation x²=25.","ta":"√25 என்பது எதிர்மறையற்ற மூலத்தைக் குறிக்கும். இதை x²=25 என்ற சமன்பாட்டுடன் குழப்ப வேண்டாம்."}];
  const pitfalls=[{"en":"There is no single 'next' rational number after 1/2; another fraction always fits between two different ones.","ta":"1/2-க்கு அடுத்த ஒரே ஒரு விகிதமுறு எண் இல்லை; எந்த இரண்டு வெவ்வேறு விகிதமுறு எண்களுக்கிடையிலும் இன்னொரு பின்னம் உண்டு."},{"en":"The decimal of 1/6 repeats after its first digit. Repetition need not start immediately.","ta":"1/6-இன் தசமம் முதல் இலக்கத்திற்குப் பின் மீள்கிறது. மீள்தொடர் உடனே தொடங்க வேண்டியதில்லை."},{"en":"A location rounded to 1.41 is not the exact point √2. Refining an interval increases precision, not the actual number.","ta":"1.41 என்பது √2-இன் துல்லிய இடம் அல்ல. இடைவெளியைச் சுருக்குவது துல்லியத்தை உயர்த்தும்; எண்ணை மாற்றாது."},{"en":"√(a+b) is generally not √a+√b. Also, the principal even root is not negative.","ta":"√(a+b) பொதுவாக √a+√b அல்ல. மேலும், முதன்மை இரட்டைப்படை மூலம் எதிர்மறை அல்ல."},{"en":"Do not add unlike radicals: √2+√3 cannot be simplified to √5.","ta":"வெவ்வேறு முறுடுகளைச் சேர்க்க வேண்டாம்: √2+√3 என்பது √5 அல்ல."},{"en":"Use the opposite sign of the whole two-term expression as the conjugate; multiplying only by the root does not remove both terms.","ta":"இரு உறுப்புக் கோவையின் நடுக்குறியை மாற்றிய இணை முறுடைப் பயன்படுத்துக; மூலத்தால் மட்டும் பெருக்குவது போதாது."},{"en":"0.00064 is 6.4×10⁻⁴, not 6.4×10⁴. The negative exponent makes the value small.","ta":"0.00064 என்பது 6.4×10⁻⁴; 6.4×10⁴ அல்ல. எதிர்மறை அடுக்கு எண்ணைச் சிறியதாக்கும்."},{"en":"√25=±5 is false. Only the equation x²=25 has both ±5 as solutions.","ta":"√25=±5 என்பது தவறு. x²=25 என்ற சமன்பாட்டுக்கு மட்டுமே ±5 ஆகிய இரு தீர்வுகள் உள்ளன."}];
  stage.foundation=ladders[index];
  stage.hint=hints[index];
  stage.pitfall=pitfalls[index];
});
